235	/**
236	 * Determines if the value is a JavaScript Class.
237	 * Note that class is a class function in JavaScript.
238	 *
239	 * @param val Any value
240	 * @returns boolean If it's a JavaScript Class returns true
241	 */
242	export const isClass = (val: any): boolean => {
243	  if (typeof val !== 'function') return false; // Not a function, so not a class function either
244	
245	  if (!val.prototype) return false; // Arrow function, so not a class
246	
247	  // Finally -> distinguish between a normal function and a class function
248	  if (getOwnPropertyDescriptor(val, 'prototype')?.writable) {
249	    // Has writable prototype
250	    return false; // Normal function
251	  } else {
252	    return true; // Class -> Not a function
253	  }
254	};
255	/**
256	 * Creates props with defaults in defineComponent() style.
257	 *
258	 * Merge defaults regular object with Vue types object
259	 * declared in defineComponent() style.
260	 *
261	 * This is made so that the defaults can be declared "as they are"
262	 * without requiring objects to be function callbacks returning an object.
263	 *
264	 * // You don't need to wrap objects in () => ({ nest: { nest :{} } })
265	 * // You can just delcare them normally.
266	 * const defaults = {
267	 *    nest: {
268	 *      nest
269	 *    }
270	 * }
271	 *
272	 * This function will create the Vue expected callbacks for Objects, Arrays & Classes
273	 * but leave primitive properties and functions intact so that
274	 * the final object is fully defineComponent() style compatible.
275	 *
276	 * @param defaults Regular object of default key -> values
277	 * @param typedProps Props declared in defineComponent() style with type and possibly required declared, but without default
278	 * @returns Props declared in defineComponent() style with all properties having default property declared.
279	 */
280	export const propsWithDefaults = <T extends VuePropsObject>(
281	  defaults: Record<string, any>,
282	  typedProps: T,
283	  // Optional: Allows user to pass a custom cloner if structuredClone isn't enough
284	  customCloner?: (val: any) => any
285	): VuePropsWithDefaults<T> => {
286	  for (const prop in typedProps) {
287	    const def = defaults?.[prop];
288	    const typed = typedProps[prop];
289	
290	    if (typed.required || def === undefined) continue;
291	
292	    if (typeof def === 'object' && def !== null) {
293	      typedProps[prop].default = () =>
294	        customCloner ? customCloner(def) : structuredClone(def);
295	    } else {
296	      if (isClass(def)) {
297	        typedProps[prop].default = () => def;
298	      } else {
299	        typedProps[prop].default = def;
300	      }
301	    }
302	  }
303	  return typedProps as VuePropsWithDefaults<T>;
304	};
