      class Foo {
        get x() {
          return ref(1);
        }
        bump() {
          return 1;
        }
      }
      const RFoo = Reactive(Foo);
      const inst = new RFoo();
      // No deep reactive proxy is created per instance.
      expect(isReactive(inst)).toBe(false);
      // toRaw() on a plain instance returns the instance itself.
      expect(toRaw(inst)).toBe(inst);
    });
  });

