import { describe, it, expect } from 'vitest';
import { computed, reactive, ref } from 'vue';
import { Reactive } from '../Reactive';
import { ivue, iref } from '../ivue';

// ---- Reactive.ts (v2) style: getters return refs/computeds, plain instance ----
class $V2 {
  get w() {
    return ref(1);
  }
  get h() {
    return ref(2);
  }
  get area() {
    return computed(() => (this as any).w.value * (this as any).h.value);
  }
  update() {
    (this as any).w.value++;
  }
}
const V2 = Reactive($V2);

// ---- ivue.ts (v1) style: iref fields, getters become computeds, reactive proxy ----
class V1 {
  w = iref(1);
  h = iref(2);
  get area() {
    return (this as any).w * (this as any).h;
  }
  update() {
    (this as any).w++;
  }
}

// ---- native Vue 3 composable (idiomatic) ----
const useItem = () => {
  const w = ref(1);
  const h = ref(2);
  const area = computed(() => w.value * h.value);
  const update = () => w.value++;
  return { w, h, area, update };
};

// ---- native Vue 3 reactive() of a plain class instance ----
class PlainNative {
  w = 1;
  h = 2;
  get area() {
    return this.w * this.h;
  }
  update() {
    this.w++;
  }
}

const N = 100_000;
const time = (label: string, fn: () => void) => {
  const t0 = performance.now();
  fn();
  const dt = performance.now() - t0;
  console.log(`  ${label.padEnd(34)} ${dt.toFixed(1)}ms`);
  return dt;
};

describe('micro-benchmark (informational, always passes)', () => {
  it(`instantiation of ${N} instances (pure allocation, no access)`, () => {
    console.log(`\n[INSTANTIATION x${N}]`);
    const a = new Array(N);
    const b = new Array(N);
    const c = new Array(N);
    const d = new Array(N);
    const tV2 = time('Reactive.ts  new V2()', () => {
      for (let i = 0; i < N; i++) a[i] = new V2();
    });
    const tV1 = time('ivue.ts      ivue(V1)', () => {
      for (let i = 0; i < N; i++) b[i] = ivue(V1 as any);
    });
    const tComp = time('native       useItem()', () => {
      for (let i = 0; i < N; i++) c[i] = useItem();
    });
    const tReac = time('native       reactive(new Plain())', () => {
      for (let i = 0; i < N; i++) d[i] = reactive(new PlainNative());
    });
    console.log(
      `  → Reactive.ts is ${(tV1 / tV2).toFixed(1)}x faster than ivue(), ` +
        `${(tComp / tV2).toFixed(1)}x vs composable, ` +
        `${(tReac / tV2).toFixed(1)}x vs reactive()`
    );
    expect(a.length).toBe(N);
  });

  it(`first-access materialization: read .area on ${N} instances`, () => {
    console.log(`\n[CONSTRUCT + FIRST READ area x${N}]`);
    const tV2 = time('Reactive.ts  new+area.value', () => {
      for (let i = 0; i < N; i++) {
        const o: any = new V2();
        void o.area.value;
      }
    });
    const tV1 = time('ivue.ts      ivue+area', () => {
      for (let i = 0; i < N; i++) {
        const o: any = ivue(V1 as any);
        void o.area;
      }
    });
    const tComp = time('native       useItem+area.value', () => {
      for (let i = 0; i < N; i++) {
        const o = useItem();
        void o.area.value;
      }
    });
    const tReac = time('native       reactive+area', () => {
      for (let i = 0; i < N; i++) {
        const o: any = reactive(new PlainNative());
        void o.area;
      }
    });
    console.log(
      `  → ratios vs Reactive.ts: ivue ${(tV1 / tV2).toFixed(1)}x, ` +
        `composable ${(tComp / tV2).toFixed(1)}x, reactive ${(tReac / tV2).toFixed(1)}x`
    );
    expect(true).toBe(true);
  });
});

