describe('WatchDemo (browser behavior verification)', () => {
  it('start → change → watcher fires → stop → dispose teardown', async () => {
    const w = mount(WatchDemo);

    // initial state
    expect(w.text()).toContain('20°');
    expect(w.text()).toContain('Comfortable');
    expect(w.text()).toContain('not allocated');

    // start watching (allocates the lazy effect scope)
    await btn(w, 'Start watching')!.trigger('click');
    await flushPromises();
    expect(w.text()).toContain('WATCHING');
    expect(w.text()).toContain('allocated');

    // change temperature → watcher should fire
    await btn(w, '+ 1')!.trigger('click');
    await flushPromises();
    expect(w.text()).toContain('21°');
    expect(w.text()).toContain('20°C → 21°C'); // log entry present
    expect(w.text()).toContain('Times fired'); // panel present

    // bump twice more
    await btn(w, '+ 1')!.trigger('click');
    await btn(w, '+ 1')!.trigger('click');
    await flushPromises();
    expect(w.text()).toContain('23°');

    // stop watching → further changes must NOT log
    await btn(w, 'Stop watching')!.trigger('click');
    await flushPromises();
    expect(w.text()).toContain('IDLE');
    await btn(w, '− 1')!.trigger('click'); // 23 -> 22
    await flushPromises();
    expect(w.text()).toContain('22°');
    // log still references the last logged transition (no new 23->22 entry while idle)
    expect(w.text()).not.toContain('23°C → 22°C');

    // dispose → fresh instance, state reset to defaults
    await btn(w, 'Dispose instance')!.trigger('click');
    await flushPromises();
    expect(w.text()).toContain('20°'); // reinitialized
    expect(w.text()).toContain('IDLE');
    expect(w.text()).toContain('not allocated');
  });
});

