import { describe, expect, it } from 'vitest';
import { computed, ref } from 'vue';
import { Reactive } from '../Reactive';

// Flat class (matches the earlier benchmark exactly)
class $Flat {
  get w() { return ref(1); }
  get h() { return ref(2); }
  get area() { return computed(() => (this as any).w.value * (this as any).h.value); }
  update() { (this as any).w.value++; }
}
const Flat = Reactive($Flat);

// Deep 4-level hierarchy (the parent/grandparent case)
class D1 { get base() { return ref(10); } get tag() { return computed(() => `L1:${(this as any).base.value}`); } }
class D2 extends D1 { get tag() { return computed(() => `L2(${super.tag.value})`); } }
class D3 extends D2 { get extra() { return ref(5); } get tag() { return computed(() => `L3[${super.tag.value}]`); } }
class D4 extends D3 { get tag() { return computed(() => `L4{${super.tag.value}}`); } }
const Deep = Reactive(D4);

const N = 100_000;
const time = (label: string, fn: () => void) => {
  const t0 = performance.now();
  fn();
  const dt = performance.now() - t0;
  console.log(`  ${label.padEnd(38)} ${dt.toFixed(1)}ms`);
  return dt;
};

describe('bench (informational)', () => {
  it(`flat: allocate + first-read ${N}`, () => {
    console.log('\n[NEW Reactive.ts]');
    const a = new Array(N);
    time('flat allocate (new Flat())', () => { for (let i = 0; i < N; i++) a[i] = new Flat(); });
    time('flat construct + first area.value', () => {
      for (let i = 0; i < N; i++) { const o: any = new Flat(); void o.area.value; }
    });
    time('deep4 allocate (new Deep())', () => { for (let i = 0; i < N; i++) new Deep(); });
    time('deep4 construct + tag.value (4-level chain)', () => {
      for (let i = 0; i < N; i++) { const o: any = new Deep(); void o.tag.value; }
    });
    expect(a.length).toBe(N);
  });
});

import { describe, expect, it } from 'vitest';
import { computed, ref } from 'vue';
import { Reactive as ReactiveNew } from '../Reactive';
import { Reactive as ReactiveOld } from '../Reactive.old';

// Identical class bodies, one per engine (Reactive mutates the prototype, so the
// classes must be distinct to avoid one engine's transform shadowing the other).
const makeFlat = (R: any) => {
  class Flat {
    get w() { return ref(1); }
    get h() { return ref(2); }
    get area() { return computed(() => (this as any).w.value * (this as any).h.value); }
  }
  return R(Flat);
};
const makeDeep = (R: any) => {
  class D1 { get base() { return ref(10); } get tag() { return computed(() => `L1:${(this as any).base.value}`); } }
  class D2 extends D1 { get tag() { return computed(() => `L2(${super.tag.value})`); } }
  class D3 extends D2 { get extra() { return ref(5); } get tag() { return computed(() => `L3[${super.tag.value}]`); } }
  class D4 extends D3 { get tag() { return computed(() => `L4{${super.tag.value}}`); } }
  return R(D4);
};

const FlatOld = makeFlat(ReactiveOld);
const FlatNew = makeFlat(ReactiveNew);
const DeepOld = makeDeep(ReactiveOld);
const DeepNew = makeDeep(ReactiveNew);

// sink prevents dead-code elimination without retaining arrays (10M-safe)
let sink = 0;

const time = (label: string, fn: () => void) => {
  const t0 = performance.now();
  fn();
  const dt = performance.now() - t0;
  console.log(`  ${label.padEnd(30)} ${dt.toFixed(0).padStart(6)} ms`);
  return dt;
};

const allocFlat = (C: any, n: number) => () => { let last: any; for (let i = 0; i < n; i++) last = new C(); sink += last ? 1 : 0; };
const readFlat = (C: any, n: number) => () => { let s = 0; for (let i = 0; i < n; i++) { const o: any = new C(); s += o.area.value; } sink += s; };
const readDeep = (C: any, n: number) => () => { let s = 0; for (let i = 0; i < n; i++) { const o: any = new C(); s += o.tag.value.length; } sink += s; };

describe('bench: old (getSuperKey) vs new (inline Symbol) at scale', () => {
  it('1M and 10M', () => {
    // warm up JIT
    allocFlat(FlatOld, 50000)(); allocFlat(FlatNew, 50000)();
    readFlat(FlatOld, 50000)(); readFlat(FlatNew, 50000)();
    readDeep(DeepOld, 50000)(); readDeep(DeepNew, 50000)();

    for (const N of [1_000_000, 10_000_000]) {
      console.log(`\n========== N = ${N.toLocaleString()} ==========`);
      console.log('[flat: allocate only]');
      time('OLD getSuperKey', allocFlat(FlatOld, N));
      time('NEW inline Symbol', allocFlat(FlatNew, N));
      console.log('[flat: construct + first area.value]');
      time('OLD getSuperKey', readFlat(FlatOld, N));
      time('NEW inline Symbol', readFlat(FlatNew, N));
      console.log('[deep 4-level: construct + tag.value chain]');
      time('OLD getSuperKey', readDeep(DeepOld, N));
      time('NEW inline Symbol', readDeep(DeepNew, N));
    }
    expect(sink).toBeGreaterThan(0);
  }, 600000);
});

