import { describe, expect, it } from 'vitest';
import { ref } from 'vue';
import { Reactive } from '../Reactive';

// ---- v2 Reactive class ----
class $Phys {
  get w() { return ref(3); }
  get h() { return ref(4); }
  physics() {
    return Math.sqrt(Math.pow((this as any).w.value, 2) + Math.pow((this as any).h.value, 2)) * Math.random();
  }
}
const Phys = Reactive($Phys);

// ---- native composable (identical body) ----
const usePhys = () => {
  const w = ref(3), h = ref(4);
  const physics = () => Math.sqrt(Math.pow(w.value, 2) + Math.pow(h.value, 2)) * Math.random();
  return { w, h, physics };
};

// ---- plain object + method (no reactivity at all) ----
const plain = { w: 3, h: 4, physics() { return Math.sqrt(Math.pow(this.w, 2) + Math.pow(this.h, 2)) * Math.random(); } };

let sink = 0;
const time = (label: string, fn: () => void) => {
  const t0 = performance.now();
  fn();
  const dt = performance.now() - t0;
  console.log(`  ${label.padEnd(34)} ${dt.toFixed(0).padStart(6)} ms`);
};

describe('fair function-call bench (identical bodies)', () => {
  it('N calls', () => {
    const inst: any = new Phys();
    const { physics: nativeFn } = usePhys();
    const v2Cached = inst.physics; // cache the bound method once
    // warm
    for (let i = 0; i < 100000; i++) { sink += nativeFn(); sink += v2Cached(); sink += inst.physics(); sink += plain.physics(); }

    for (const N of [1_000_000, 10_000_000]) {
      console.log(`\n===== ${N.toLocaleString()} calls =====`);
      time('plain object method', () => { let s = 0; for (let i = 0; i < N; i++) s += plain.physics(); sink += s; });
      time('native composable fn()', () => { let s = 0; for (let i = 0; i < N; i++) s += nativeFn(); sink += s; });
      time('v2 method (cached ref)', () => { let s = 0; for (let i = 0; i < N; i++) s += v2Cached(); sink += s; });
      time('v2 inst.method() (retrieve each)', () => { let s = 0; for (let i = 0; i < N; i++) s += inst.physics(); sink += s; });
    }
    expect(sink).not.toBe(0);
  }, 600000);
});

